'<a class="post-image-link" href="' + url + '">' + image + '</a>' + tag +
'<div class="post-info"><h2 class="post-title">' + title + '</h2>' +
'<div class="post-meta">' + author + date + '</div>' + snippet + '</div>' +
'</div></li>';
